#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

cd "$(dirname "$0")/.."
# Production values live here: gitignored and NEVER read by Next.js (so never baked into the bundle).
ENV_FILE=".secrets.production"
DOMAIN="crownd.dev"
WR="npx --yes wrangler"

banner "Crownd · Lançamento em $DOMAIN (Cloudflare)"

registered() { [[ "$(curl -s -o /dev/null -w '%{http_code}' "https://pubapi.registry.google/rdap/domain/$DOMAIN")" == "200" ]]; }
collapse_double() {
  local v="$1" h=$(( ${#1} / 2 ))
  if (( ${#v} % 2 == 0 && h > 0 )) && [[ "${v:0:h}" == "${v:h}" ]]; then printf '%s' "${v:0:h}"; else printf '%s' "$v"; fi
}
rand_hex() { node -e "process.stdout.write(require('crypto').randomBytes(16).toString('hex'))"; }
logged_in() { $WR whoami 2>/dev/null | grep -qi "associated with the email"; }

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Conta Cloudflare"
say "Vamos conectar o Wrangler (CLI oficial da Cloudflare) à sua conta."
note "Se ainda não tem conta: https://dash.cloudflare.com/sign-up (grátis)."
if logged_in; then
  note "Já conectado."
else
  step "Vai abrir o navegador: entre na Cloudflare e clique em 'Allow'."
  $WR login || warn "Login não concluído."
fi
if ! logged_in; then
  warn "Sem login na Cloudflare não dá para publicar. Rode de novo: npm.cmd run launch"
  finish; return
fi
pause "Enter para continuar"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Registrar o domínio $DOMAIN"
if registered; then
  note "$DOMAIN já está registrado."
  if ! confirm "Ele está na SUA conta Cloudflare?"; then
    warn "O domínio é de outra pessoa: troque DOMAIN neste wizard, em wrangler.jsonc e em .env.production."
    finish; return
  fi
else
  say "Domínios .dev saem a preço de custo na Cloudflare (sem margem) e já exigem HTTPS."
  open_url "https://dash.cloudflare.com/?to=/:account/domains/register"
  step "Em 'Domain Registration → Register Domains', busque $DOMAIN, clique em 'Purchase' e conclua o pagamento."
  step "Deixe a renovação automática LIGADA (perder o domínio derruba todo o SEO)."
  pause "Enter quando a compra estiver confirmada"
  for _ in $(seq 1 20); do registered && break; note "aguardando o registro propagar…"; sleep 15; done
  if registered; then note "$DOMAIN registrado."; else warn "Ainda não aparece como registrado. Continue; a etapa 7 confere de novo."; fi
fi
pause "Enter para continuar"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Banco de dados (Cloudflare D1)"
DB_ID=$($WR d1 list --json 2>/dev/null | node scripts/cf-config.mjs find-d1 || true)
if [[ -z "$DB_ID" ]]; then
  say "Criando o banco crownd-db…"
  DB_ID=$($WR d1 create crownd-db 2>&1 | grep -oE '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' | head -n1 || true)
fi
if [[ -z "$DB_ID" ]]; then
  warn "Não consegui criar nem encontrar o D1. Veja: npx wrangler d1 list"
  finish; return
fi
node scripts/cf-config.mjs set-d1 "$DB_ID"
say "Aplicando o schema (migrations/)…"
if ! $WR d1 migrations apply crownd-db --remote; then
  warn "Falha ao migrar o banco."
  finish; return
fi
pause "Enter para continuar"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Pagamentos reais (Stripe LIVE)"
say "Sem chave LIVE o site entra no ar normalmente, mas os lances mostram 'pagamentos abrem em breve'."
note "Uma chave de teste nunca libera lances em produção (trava de segurança do app)."
STRIPE_LIVE_SECRET_KEY=""
if confirm "Sua conta Stripe já está ATIVADA para receber pagamentos reais?"; then
  open_url "https://dashboard.stripe.com/apikeys"
  step "Desligue o 'Test mode'. Na linha 'Secret key', clique em 'Reveal live key' e copie (sk_live_…)."
  while true; do
    ask_secret STRIPE_LIVE_SECRET_KEY "Cole a chave LIVE uma única vez (fica oculta):"
    STRIPE_LIVE_SECRET_KEY=$(collapse_double "$STRIPE_LIVE_SECRET_KEY")
    if [[ ! "$STRIPE_LIVE_SECRET_KEY" =~ ^(sk|rk)_live_ ]]; then warn "Esperado sk_live_…"; continue; fi
    if curl -s -u "$STRIPE_LIVE_SECRET_KEY:" https://api.stripe.com/v1/balance | grep -q '"error"'; then
      warn "O Stripe recusou essa chave. Copie de novo."
      continue
    fi
    note "Chave LIVE aceita pelo Stripe."
    break
  done
  write_env STRIPE_LIVE_SECRET_KEY "$STRIPE_LIVE_SECRET_KEY"
else
  SKIPPED+=("Ativar a conta Stripe (Settings → Business details) e rodar npm.cmd run launch de novo para ligar os lances")
fi
pause "Enter para continuar"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Identificação do vendedor (página /legal)"
say "A lei brasileira (Decreto 7.962/2013) e a de vários países exigem identificar quem vende online."
note "Esses dados aparecem publicamente em $DOMAIN/{país}/legal."
ask LEGAL_ENTITY "Nome completo ou razão social:"
ask LEGAL_TAX_ID "CPF ou CNPJ (ou o Tax ID da empresa):"
ask LEGAL_ADDRESS "Endereço (no mínimo cidade, estado e país):"
ask LEGAL_EMAIL "E-mail de contato público:"
write_env LEGAL_ENTITY "$LEGAL_ENTITY"
write_env LEGAL_TAX_ID "$LEGAL_TAX_ID"
write_env LEGAL_ADDRESS "$LEGAL_ADDRESS"
write_env LEGAL_EMAIL "$LEGAL_EMAIL"
CLICK_SALT=$(_existing CLICK_SALT || true); [[ -n "$CLICK_SALT" ]] || CLICK_SALT=$(rand_hex)
INDEXNOW_KEY=$(_existing INDEXNOW_KEY || true); [[ -n "$INDEXNOW_KEY" ]] || INDEXNOW_KEY=$(rand_hex)
write_env CLICK_SALT "$CLICK_SALT"
write_env INDEXNOW_KEY "$INDEXNOW_KEY"
pause "Enter para publicar"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Publicar o site"
say "Build, verificação de segurança do pacote e deploy (cerca de 2 minutos)…"
note "Se o Wrangler pedir para escolher um subdomínio workers.dev, aceite: é o endereço provisório."
if ! npm run deploy; then
  warn "O deploy falhou: veja o erro acima."
  finish; return
fi
say "Enviando os segredos para a Cloudflare (criptografados, fora do código)…"
SECRETS_JSON=$(mktemp)
STRIPE_SECRET_KEY="$STRIPE_LIVE_SECRET_KEY" CLICK_SALT="$CLICK_SALT" INDEXNOW_KEY="$INDEXNOW_KEY" \
  LEGAL_ENTITY="$LEGAL_ENTITY" LEGAL_TAX_ID="$LEGAL_TAX_ID" LEGAL_ADDRESS="$LEGAL_ADDRESS" LEGAL_EMAIL="$LEGAL_EMAIL" \
  node scripts/cf-config.mjs secrets-json > "$SECRETS_JSON"
$WR secret bulk "$SECRETS_JSON" || warn "Falha ao enviar os segredos."
rm -f "$SECRETS_JSON"
pause "Enter para conectar o domínio"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Conectar $DOMAIN"
if ! registered; then
  warn "$DOMAIN ainda não aparece como registrado. O site já está no ar no endereço workers.dev mostrado acima."
  SKIPPED+=("Conectar $DOMAIN: depois do registro, rode npm.cmd run launch de novo")
else
  node scripts/cf-config.mjs enable-domain
  if npm run deploy -- --skip-build; then
    say "Aguardando o certificado HTTPS de $DOMAIN (pode levar alguns minutos)…"
    for _ in $(seq 1 40); do
      [[ "$(curl -s -o /dev/null -w '%{http_code}' "https://$DOMAIN/robots.txt")" == "200" ]] && break
      sleep 10
    done
    if [[ "$(curl -s -o /dev/null -w '%{http_code}' "https://$DOMAIN/robots.txt")" == "200" ]]; then
      note "https://$DOMAIN no ar!"
    else
      warn "Ainda propagando. Tente abrir em alguns minutos."
    fi
  else
    node scripts/cf-config.mjs disable-domain
    warn "A Cloudflare recusou o domínio (ele precisa estar na mesma conta). Corrija e rode de novo."
  fi
fi
pause "Enter para continuar"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Webhook do Stripe (produção)"
if [[ -z "$STRIPE_LIVE_SECRET_KEY" ]]; then
  note "Pulado: ainda sem chave LIVE."
else
  say "Criando o endpoint https://$DOMAIN/api/webhooks/stripe pela API…"
  STRIPE_SECRET_KEY="$STRIPE_LIVE_SECRET_KEY" node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON \
    scripts/stripe-webhook.mts --url "https://$DOMAIN" --env-file "$ENV_FILE" || warn "Falha ao criar o webhook."
  WHSEC=$(_existing STRIPE_WEBHOOK_SECRET || true)
  if [[ -n "$WHSEC" ]]; then
    printf '%s' "$WHSEC" | $WR secret put STRIPE_WEBHOOK_SECRET && note "Segredo do webhook enviado à Cloudflare."
  else
    warn "Sem segredo do webhook. Rode: npm.cmd run stripe:webhook -- --url https://$DOMAIN --recreate"
  fi
fi
pause "Enter para a verificação final"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Verificação final"
say "Auditando todas as páginas do sitemap em produção (hreflang, canonical, H1, JSON-LD…)…"
npm run --silent seo:check -- --base "https://$DOMAIN" || warn "A auditoria apontou itens: veja acima."
open_url "https://$DOMAIN"
SKIPPED+=("Google Search Console: adicionar a propriedade de Domínio $DOMAIN (verificação automática via Cloudflare) e enviar /sitemap.xml")
SKIPPED+=("Bing Webmaster Tools (importar do Search Console), Naver Search Advisor (Coreia) e Yandex (Turquia)")
SKIPPED+=("Revisão nativa dos textos das edições em outros idiomas antes de divulgar nelas")
pause "Enter para finalizar"

finish
}

run_wizard "$@"; exit
